using System;using System.Collections.Generic;using Game.Components;using Game.Configs;using Unity.Entities;namespace Game.Runtime{
internal sealed class SourceCampPrefabBinding{internal readonly LogicalCatalogPrefab Logical;internal readonly SourceUnitPrefab Command;internal SourceCampPrefabBinding(LogicalCatalogPrefab logical,SourceUnitPrefab command){Logical=logical;Command=command;}}
internal sealed class SourceCampIdentityMap{
 readonly Dictionary<SourceUnitPrefab,LogicalCatalogPrefab> logical=new Dictionary<SourceUnitPrefab,LogicalCatalogPrefab>();readonly Dictionary<LogicalCatalogPrefab,SourceUnitPrefab> command=new Dictionary<LogicalCatalogPrefab,SourceUnitPrefab>();
 internal SourceCampIdentityMap(EntityManager em,CatalogPrefabStore store,IReadOnlyList<SourceCampPrefabBinding> sourceBindings,bool sourceBindingDomainComplete){if(!sourceBindingDomainComplete||sourceBindings==null)throw new NotSupportedException("Complete authored prefab-to-template identity mapping required");foreach(var x in sourceBindings){if(x?.Logical==null||x.Command==null||!em.Exists(x.Command.Template)||!string.Equals(x.Logical.name,x.Command.name,StringComparison.Ordinal)||logical.ContainsKey(x.Command)||command.ContainsKey(x.Logical))throw new NotSupportedException("Unique same-source prefab/template identity required, no name-only lookup");store.TryGetUnit(x.Logical,out _);logical.Add(x.Command,x.Logical);command.Add(x.Logical,x.Command);}}
 internal LogicalCatalogPrefab Logical(SourceUnitPrefab prefab){if(prefab==null)return null;if(!logical.TryGetValue(prefab,out var p))throw new NotSupportedException("Source command prefab outside closed logical identity map");return p;}internal SourceUnitPrefab Command(LogicalCatalogPrefab prefab){if(prefab==null)return null;if(!command.TryGetValue(prefab,out var p))throw new NotSupportedException("Logical prefab missing actual command/template identity");return p;}}
internal sealed class SourceGameplayPrefabBinding{internal readonly SourceUnitPrefab Command;internal readonly string SourceIdentity;internal SourceGameplayPrefabBinding(SourceUnitPrefab command,string sourceIdentity){if(command==null||string.IsNullOrEmpty(sourceIdentity))throw new ArgumentException("Pinned source prefab identity required");Command=command;SourceIdentity=sourceIdentity;}}
internal readonly struct SourceUnitGameplayPrefabIdentity{internal readonly SourceUnitPrefab Prefab;internal readonly string Name,Identity;internal SourceUnitGameplayPrefabIdentity(SourceUnitPrefab prefab,string name,string identity){Prefab=prefab;Name=name;Identity=identity;}}
internal sealed class SourceCampGameplayIdentityMap{
 readonly Dictionary<SourceUnitPrefab,SourceUnitGameplayPrefabIdentity> identities=new Dictionary<SourceUnitPrefab,SourceUnitGameplayPrefabIdentity>();readonly List<SourceUnitGameplayPrefabIdentity> ordered=new List<SourceUnitGameplayPrefabIdentity>();internal IReadOnlyList<SourceUnitGameplayPrefabIdentity> Configured=>ordered.AsReadOnly();
 internal SourceCampGameplayIdentityMap(IReadOnlyList<SourceUnitPrefab> expectedOrder,IReadOnlyList<SourceGameplayPrefabBinding> sourceBindings){if(expectedOrder==null||sourceBindings==null||expectedOrder.Count==0||expectedOrder.Count!=sourceBindings.Count)throw new NotSupportedException("Exact complete gameplay prefab identity bindings required");var sourceIds=new HashSet<string>(StringComparer.Ordinal);var names=new HashSet<string>(StringComparer.Ordinal);for(int i=0;i<expectedOrder.Count;i++){var prefab=expectedOrder[i];var binding=sourceBindings[i];if(prefab==null||binding==null||!ReferenceEquals(prefab,binding.Command)||string.IsNullOrEmpty(prefab.name)||!System.Text.RegularExpressions.Regex.IsMatch(binding.SourceIdentity,"^[0-9a-f]{32}:[0-9]+$")||identities.ContainsKey(prefab)||!sourceIds.Add(binding.SourceIdentity)||!names.Add(prefab.name))throw new NotSupportedException("Unique ordered source prefab identity required");var identity=new SourceUnitGameplayPrefabIdentity(prefab,prefab.name,binding.SourceIdentity);identities.Add(prefab,identity);ordered.Add(identity);}}
 internal SourceUnitGameplayPrefabIdentity Identity(SourceUnitPrefab prefab){if(prefab==null||!identities.TryGetValue(prefab,out var value))throw new NotSupportedException("Prefab outside closed source gameplay identity map");return value;}internal SourceUnitPrefab Command(LogicalCatalogPrefab logicalPrefab){if(logicalPrefab==null)throw new NotSupportedException("Logical UI selection missing");foreach(var row in ordered)if(string.Equals(row.Identity,logicalPrefab.Identity,StringComparison.Ordinal)&&string.Equals(row.Name,logicalPrefab.name,StringComparison.Ordinal))return row.Prefab;throw new NotSupportedException("UI selection outside exact source gameplay identity domain");}internal void RequireSameConfiguredOrder(IReadOnlyList<SourceUnitPrefab> actual){if(actual==null||actual.Count!=ordered.Count)throw new NotSupportedException("Actual source configured-unit order differs from pinned gameplay identity domain");for(int i=0;i<actual.Count;i++)if(!ReferenceEquals(actual[i],ordered[i].Prefab))throw new NotSupportedException("Actual source configured-unit identity/order changed");}}
internal sealed class SourceCampReadScope:IDisposable{[ThreadStatic]internal static SourceCampReadScope Current;internal readonly EntityManager Em;internal readonly Entity Session;internal readonly SourceCampGameplayIdentityMap Map;internal readonly SourceCampBuildingDomain BuildingDomain;readonly CatalogMetadataReadScope catalog;
 internal SourceCampReadScope(EntityManager em,CatalogPrefabStore store,CatalogPublicFacts facts,SourceCampGameplayIdentityMap map,SourceCampSingleProducerFixtureScope fixtureScope=null,Entity expectedSession=default,SourceCampBuildingDomain buildingDomain=null){if(Current!=null)throw new NotSupportedException("Nested availability context unsupported");Em=em;Map=map;using var q=em.CreateEntityQuery(typeof(SkirmishExpandedSessionComponent),typeof(SkirmishProductionCatalogRecord));if(q.CalculateEntityCount()!=1)throw new NotSupportedException("One actual source session/catalog required");var owner=q.GetSingletonEntity();Session=owner;BuildingDomain=buildingDomain;if(expectedSession!=Entity.Null&&owner!=expectedSession)throw new NotSupportedException("Same current source session required");if(em.GetComponentData<SkirmishExpandedSessionComponent>(owner).Phase!=Game.Skirmish.Contracts.SkirmishSessionPhase.Playing)throw new NotSupportedException("Only Playing source availability admitted");var record=em.GetComponentObject<SkirmishProductionCatalogRecord>(owner).Catalog;var setup=record?.Setup;if(fixtureScope?.Authority?.IsS003Fixture==true){RequireS003FixtureSetup(fixtureScope.Authority,setup);}else SourceGroundMissionFamily.RequireCatalogSetup(setup);catalog=new CatalogMetadataReadScope(em,store,facts,record);Current=this;}
 internal static void RequireS003FixtureSetup(SourceProducerRecipeAuthority authority,SkirmishResolvedSetup setup){if(authority?.IsS003Fixture!=true||!authority.MatchesSetup(setup))throw new NotSupportedException("Exact current S003 fixture authority/setup required");try{SourcePaidCatalogSetupGuard.RequireS003(setup);}catch(NotSupportedException){throw new NotSupportedException("Exact current S003 fixture authority/setup required");}}
 public void Dispose(){if(!ReferenceEquals(Current,this))throw new InvalidOperationException("Availability context ownership lost");Current=null;catalog.Dispose();}}
internal static class SourceCampCatalogPolicy{internal static bool Allows(EntityManager em,SourceUnitPrefab prefab,bool building){var c=SourceCampReadScope.Current;if(c!=null){if(!ReferenceEquals(c.Em,em))throw new NotSupportedException("Exact retained source gameplay identity required");if(building){if(c.BuildingDomain==null)throw new NotSupportedException("Qualified source building factory domain required");return c.BuildingDomain.Allows(em,c.Session,prefab);}var identity=c.Map.Identity(prefab);var catalog=CatalogMetadataReadScope.Current?.Catalog;if(catalog==null)throw new NotSupportedException("Current source production catalog required");return catalog.TryRole(identity.Name,out _);}if(SourceS073LegacyCatalogScope.Current!=null)return SourceS073LegacyCatalogScope.Allows(em,prefab,building);throw new NotSupportedException("Exact retained availability world required");}}
internal static class SourceCampCatalogTokenAllows{internal static bool Allows(this SkirmishProductionCatalog catalog,SourceUnitPrefab prefab,bool building){var c=SourceCampReadScope.Current;if(c==null||!ReferenceEquals(catalog,CatalogMetadataReadScope.Current.Catalog))throw new NotSupportedException("Exact source catalog reference required");return SourceCampCatalogPolicy.Allows(c.Em,prefab,building);}}
